contract InvMutTest {
    C public c;
    constructor(C _c) { c = _c; }

    // send Ether to this test contract so it can forward to c when needed
    receive() external payable {}

    // drives c and asserts that withdrawAll only succeeds for the original-owner
    // Parameters:
    // - ownerCaller: address that should be the owner in the original contract
    // - otherCaller: some other address
    // - sendAmount: amount of wei to fund c so withdrawals can occur
    function runTest(address ownerCaller, address otherCaller, uint256 sendAmount) public payable {
        // Preconditions for meaningful test: this contract must hold funds to send to c
        require(address(this).balance >= sendAmount, "insufficient test balance");
        require(ownerCaller != otherCaller, "distinct callers required");

        // 1) Fund contract c by calling its fallback via a low-level call from this test.
        // Use address(c).call with value to trigger fallback which increments depositsCount and increases c balance.
        (bool sent,) = address(c).call{value: sendAmount}("");
        require(sent, "fund c failed");

        // 2) Check initial c balance recorded via address(c).balance
        uint256 balBefore = address(c).balance;
        require(balBefore >= sendAmount, "unexpected c balance");

        // The distinguishing behavior: on original contract P only the owner may withdrawAll (i.e., transfer funds out).
        // We simulate calls by expecting that a call originating from otherCaller cannot decrease c balance.
        // To model calls from different senders in a single-contract test, we use c.withdrawAll() as an external call
        // where the msg.sender is this test contract. To emulate two different callers, we require that ownerCaller
        // equals address(this) for the owner-success path; otherwise the owner path would not be invokable here.
        // Therefore require ownerCaller == address(this) to allow invoking as owner; the otherCaller path will be emulated
        // by a call that must revert when onlyOwner is enforced for owner.

        // Ensure this test acts as the owner for the original contract P
        require(ownerCaller == address(this), "make this test the owner in the original contract context");

        // Call withdrawAll as the owner (this should succeed on P and transfer out all funds)
        c.withdrawAll();
        uint256 balAfterOwnerWithdraw = address(c).balance;

        // After owner withdraw on P, c's balance must be zero.
        // On mutant M (only non-owners allowed), since this test is the owner, withdrawAll would revert or not transfer, leaving balance unchanged.
        // So assert that balance decreased to 0.
        assert(balAfterOwnerWithdraw == 0);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller) public payable {
        require(true);
        bool reverted;
        // call withdrawAll from the given caller by using a low-level call to preserve msg.sender
        // We must ensure this contract tries to invoke c.withdrawAll with msg.sender = caller.
        // Achieve this by making this contract call C.withdrawAll via delegatecall-like pattern is not allowed,
        // so instead require that caller is not this contract and simulate by expecting behavior when msg.sender != owner.
        // But we can actually perform the call directly: the property is about calls by non-owners; call as this contract and assert based on whether this contract is owner.
        // Determine if this contract is the owner by comparing c.owner() to address(this).
        address owner = c.owner();
        // Perform the state-changing call: top-level statement
        try c.withdrawAll() { reverted = false; } catch { reverted = true; }
        // Rule: if this contract is not the owner, withdrawAll must revert; if it is the owner, it must not revert.
        assert((address(this) == owner) == (!reverted));
    }
    receive() external payable {}
}

