pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz: amount to deposit and whether the adversary's fallback reverts
    function testFuzz_property(uint256 depositAmount, bool adversaryReverts) public {
        // keep deposit reasonable
        depositAmount = bound(depositAmount, 0, 1 ether);

        // deploy adversarial callee that may revert on receive
        Adversary adv = new Adversary(adversaryReverts);

        // fund this test contract so it can fund C
        vm.deal(address(this), 2 ether);

        // deposit some ether into c by calling its fallback
        // c.fallback is payable and increments depositsCount; send depositAmount
        c.call{value: depositAmount}("");

        // sanity: contract balance should equal depositAmount
        // now call withdrawAll as owner (this contract is owner by construction)
        // wrap call to observe whether withdrawAll succeeded
        bool ok;
        try c.withdrawAll{gas: gasleft()}() {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule (single assertion): On the reference implementation, when the external target
        // invoked by withdraw(uint) fails (here simulated by sending to an adversary that reverts inside receive),
        // withdrawAll uses withdraw(address(this).balance) and thus any revert from withdraw prevents balance drain;
        // therefore after calling withdrawAll the contract's balance is zero iff the call succeeded; in particular,
        // if the adversary reverts, withdrawAll must have reverted (ok==false) and contract balance must remain unchanged.
        // We assert the invariant that when the adversary reverts, withdrawAll did NOT succeed and the balance equals depositAmount.

        if (adversaryReverts) {
            // on the correct contract, withdrawAll routes through withdraw which calls transfer(msg.sender) and will bubble revert
            // so ok must be false and balance unchanged
            assertTrue(!ok && address(c).balance == depositAmount);
        } else {
            // when adversary does not revert, withdrawAll should succeed and drain the balance
            assertTrue(ok && address(c).balance == 0);
        }
    }
}

// Adversarial helper: can be configured to revert on receive to simulate a failing external party
contract Adversary {
    bool public shouldRevert;
    constructor(bool _shouldRevert) payable {
        shouldRevert = _shouldRevert;
    }
    receive() external payable {
        if (shouldRevert) revert("revert on receive");
    }
}

