        vm.deal(owner, depositAmount);
        // Make the call as owner so fallback increments depositsCount
        vm.prank(owner);
        // low-level send to trigger fallback payable
        (bool sent, ) = address(c).call{value: depositAmount}("");
        require(sent);

        // sanity: contract should now hold depositAmount
        assertEq(address(c).balance, depositAmount);

        // Now attempt to withdrawAll directing funds to the adversarial counterparty by
        // overriding withdraw to call sendMoney on the Reverter. To simulate the scenario
        // where withdraw(...) would attempt to send to a reverter and thus revert,
        // we will first set up a situation where calling withdraw(address(this).balance)
        // would cause an external call that reverts. Since C.withdraw in the reference
        // simply transfers to msg.sender, we simulate the owner being a contract that
        // forwards the call to Reverter and itself reverts on receive; however simpler
        // and direct: we will call sendMoney on c (which uses low-level call) to send to
        // the Reverter, ensuring that external failing callee scenario exists. Then
        // invoking withdrawAll on the reference should route through withdraw(uint) and
        // be blocked when withdraw is overridden/guarded; to manifest the difference we
        // directly call withdrawAll as owner while making msg.sender be the Reverter by
        // doing a vm.prank to that contract address. That will make withdraw/withdrawAll
        // attempt to send to Reverter as msg.sender and trigger the revert in the
        // reference's routed path, but the mutant that uses direct transfer to msg.sender
        // will behave differently.

        // We need to simulate the owner calling withdrawAll but with msg.sender being the
        // Reverter address. So we prank as the Reverter contract.
        vm.prank(address(bad));

        // Try invoking withdrawAll as if called by the Reverter (which will cause the
        // reference implementation's routed withdraw to attempt to transfer to Reverter
        // and fail if it goes through withdraw(uint) which is callable only by owner; to
        // satisfy onlyOwner, msg.sender must equal owner => therefore we make owner be
        // the test contract; C.owner was set to msg.sender at construction (setUp), so
        // only the test contract is owner. To test the behavioral difference caused by
        // routing through withdraw(uint) vs direct transfer, we instead emulate a
        // scenario where withdraw(uint) (internal call) would cause an external call to
        // a failing callee. The simplest observable difference that holds across inputs
        // is: when an external recipient reverts on receive, attempts to send the
        // contract's balance via a low-level call (sendMoney) fail, while direct
        // transfer to that recipient reverts differently; here we drive withdrawAll and
        // then observe address(c).balance. We perform withdrawAll as owner here and
        // observe whether the contract balance changed after calling withdrawAll while
        // the adversarial recipient would reject receiving Ether if directly targeted.

        // Call withdrawAll as the real owner (this contract)
        vm.prank(owner);
        bool ok;
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        // The single assertion: for the correct contract, when an external recipient would
        // revert on receiving Ether (we had deposited into c previously), calling
        // withdrawAll as owner must NOT reduce address(c).balance (i.e., balance remains
        // depositAmount) because the routed withdraw path can be blocked by such
        // overriding/guarding behaviour; the mutant that directly transfers would change
        // the balance for some inputs — so the universal property to assert is that after
        // invoking withdrawAll in this adversarial environment, either the call reverted
        // (ok==false) or the contract balance remains unchanged. This holds for the
        // reference implementation for all inputs, and is violated by the mutant for
        // some inputs. We read address(c).balance (public surface) as required.
        assertTrue(!ok || address(c).balance == depositAmount);
    }
}

// adversarial helper that always reverts on receiving Ether
contract Reverter {
    fallback() external payable {
        revert("nope");
