        require(address(this).balance >= amount);
        bool reverted;
        try c.sendMoney{value: amount}(target, amount) { reverted = false; } catch { reverted = true; }
        // In the original contract, the owner's sendMoney call should not revert for any funded amount/target.
        assert(reverted == false);
    }
    receive() external payable { }
}

