pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address target, uint256 amount) public {
        // Keep domain wide but sensible: amount must be >= 0 and not exceed a large cap
        // but we also need the caller (owner) to have the funds to fund the contract via sending into fallback.
        // Bound amount to a reasonable range so vm.deal can handle it in typical fuzz runs.
        amount = bound(amount, 0, 1 ether);
        // Ensure target is not zero address to be a meaningful external recipient
        if (target == address(0)) target = address(1);

        // Fund the contract with `amount` from the owner so it can forward it out.
        // c.owner is msg.sender at construction (this test contract), so we must act as that owner.
        // Note: in setUp(), `c = new C()` was executed with this test contract as msg.sender, so this contract is owner.
        // Fund this test contract so it can send value to c.
        vm.deal(address(this), amount);
        // Send value into c so c has balance to forward. Use fallback by sending plain value.
        (bool sent,) = address(c).call{value: amount}("");
        require(sent, "funding failed");

        uint256 before = address(c).balance;
        // Sanity: before should be equal to amount
        // Now call sendMoney as the owner (this contract) to instruct c to send `amount` to `target`.
        // The rule: after successful sendMoney, c.balance == before - amount.
        vm.prank(address(this));
        bool ok;
        // wrap call to catch potential reverts, though both reference and mutant use require on call result
        try c.sendMoney(target, amount) {
            ok = true;
        } catch {
            ok = false;
        }

        // Single assertion: if the call succeeded, contract balance must have decreased by exactly amount.
        // This is a universal property: for all inputs where sendMoney returns successfully, reference C forwards out the funds,
        // but the mutant (calling address(this).call{value:amount}(...)) will keep the funds and thus this assertion will fail for some inputs.
        if (ok) {
            assertTrue(address(c).balance == before - amount);
        } else {
            // If sendMoney reverted, still assertTrue on a true literal would be invalid; so assert the observed revert boolean via a tautology
            // We must make exactly one assertTrue in the test. The above assertTrue executes only when ok==true.
            // When ok==false, to satisfy the rule of exactly one assertTrue we still need to assert something about c.
            // Use the property that when it reverted, the balance must be unchanged (call reverted so no value moved).
            // Enforce that as the single assertion in this branch.
            assertTrue(address(c).balance == before);
        }
    }
}
